+/// A `Set-Cookie` header for a browser's token: unreadable by script,
+/// never sent cross-site, and kept off the page files by its path.
+/// `max_age` of `Some(0)` clears it.
+fn set_cookie(name: &str, value: &str, max_age: Option<u32>) -> (String, String) {
+    let age = max_age.map_or_else(String::new, |s| format!("; Max-Age={s}"));
+    (
+        "Set-Cookie".to_owned(),
+        format!("{name}={value}; Path=/api/v1/{age}; Secure; HttpOnly; SameSite=Strict"),
+    )
+}
+
+/// One of the page's three files, for a `GET` of exactly its path;
+/// `None` for any other path or method. Public like `/info` (the page
+/// holds nothing) and matched before the API prefix, so the allowlist
+/// stays in `serve_remote`.
+fn page_reply(request: &RemoteRequest) -> Option<RemoteReply> {
+    if request.method != "GET" {
+        return None;
+    }
+    let (content_type, body) = match request.path.as_str() {
+        "/" => ("text/html; charset=utf-8", crate::web::INDEX_HTML),
+        "/app.css" => ("text/css; charset=utf-8", crate::web::APP_CSS),
+        "/app.js" => ("text/javascript; charset=utf-8", crate::web::APP_JS),
+        _ => return None,
+    };
+    Some(RemoteReply {
+        status: 200,
+        body: body.as_bytes().to_vec(),
+        authenticated: false,
+        headers: vec![
+            ("Content-Type".into(), content_type.into()),
+            ("Content-Security-Policy".into(), PAGE_CSP.into()),
+            ("Cache-Control".into(), "no-store".into()),
+            ("X-Content-Type-Options".into(), "nosniff".into()),
+        ],
+    })
+}
