+        let v6 = pairing_invite(&id, "[fe80::1]:43187", "ABCD2345");
+        assert!(v6.starts_with("https://[fe80::1]:43187/#code="), "{v6}");
+        assert!(!url.contains("token"));
+    }
+
+    #[test]
