+//! The browser page the remote port serves: three static files,
+//! embedded so the binary needs nothing beside it. They are plain DOM
+//! with no build step; `tests/remote.rs` pins what they may reference.
+
+/// `GET /`.
+pub const INDEX_HTML: &str = include_str!("../web/index.html");
